package dev.algorithmlearning.api.problems.api;
import dev.algorithmlearning.api.app.security.CurrentUser; import dev.algorithmlearning.api.problems.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class SolutionsController {private final SolutionService solutions;private final CurrentUser user;public SolutionsController(SolutionService solutions,CurrentUser user){this.solutions=solutions;this.user=user;}@GetMapping("/problems/{problemId}/solutions") List<View> list(@PathVariable UUID problemId){return solutions.list(user.id(),problemId).stream().map(View::from).toList();}@PostMapping("/problems/{problemId}/solutions") ResponseEntity<View> create(@PathVariable UUID problemId,@Valid @RequestBody Write w){var s=solutions.create(user.id(),problemId,w.toWrite());return ResponseEntity.created(URI.create("/api/v1/solutions/"+s.id())).body(View.from(s));}@PutMapping("/solutions/{id}") ResponseEntity<View> replace(@PathVariable UUID id,@Valid @RequestBody Write w){return solutions.replace(user.id(),id,w.toWrite()).map(s->ResponseEntity.ok(View.from(s))).orElseGet(()->ResponseEntity.notFound().build());}@DeleteMapping("/solutions/{id}") ResponseEntity<Void> delete(@PathVariable UUID id){return solutions.delete(user.id(),id)?ResponseEntity.noContent().build():ResponseEntity.notFound().build();}record Write(@NotBlank String language,@Size(max=100000) String code,@Size(max=20000) String explanation){SolutionWrite toWrite(){return new SolutionWrite(language,code,explanation);}}record View(UUID id,UUID problemId,String language,String code,String explanation,java.time.Instant createdAt,java.time.Instant updatedAt){static View from(Solution s){return new View(s.id(),s.problemId(),s.language(),s.code(),s.explanation(),s.createdAt(),s.updatedAt());}}}
